def _replace_w_namespace_prefix(content):
	# Replace 'w:' used as an attribute prefix with 'w-'
	# e.g., w:st="on" -> w-st="on"
	return re.sub(r'\bw:([a-zA-Z_][\w.-]*)=', r'w-\1=', content)
```

